def num_decodings(s: str) -> int:
    prev, cur = 0, 1  # ways for the prefixes of length i-1 and i, starting at i = 0
    for i, ch in enumerate(s):
        nxt = cur if ch != "0" else 0
        if i > 0 and 10 <= int(s[i - 1:i + 1]) <= 26:
            nxt += prev
        prev, cur = cur, nxt
    return cur
